  ('report.css', $RA_ASSET$/* ============================================================
   Report Artisan — design system
   Tokens first, roles everywhere. Light + dark are both
   *selected*, never an automatic flip.
   ============================================================ */

:root {
  /* --- surfaces & ink (light) --- */
  --page:        #f7f6f3;
  --surface:     #ffffff;
  --surface-2:   #fbfaf8;
  --ink:         #14131a;
  --ink-2:       #55535e;
  --ink-3:       #8b8996;
  --hairline:    #e7e4de;
  --hairline-2:  #f0eeea;
  --shadow:      0 1px 2px rgba(20,19,26,.04), 0 8px 24px -12px rgba(20,19,26,.10);
  --shadow-lg:   0 2px 4px rgba(20,19,26,.04), 0 24px 56px -24px rgba(20,19,26,.18);

  /* --- accent (overridden per theme preset) --- */
  --accent:      #2a78d6;
  --accent-ink:  #1c5cab;
  --accent-soft: #eaf2fd;
  --on-accent:   #ffffff;

  /* --- categorical series (validated set, light steps) --- */
  --s1: #2a78d6; --s2: #eb6834; --s3: #1baf7a; --s4: #eda100;
  --s5: #e87ba4; --s6: #008300; --s7: #4a3aa7; --s8: #e34948;

  /* --- status (fixed, never themed) --- */
  --ok: #0ca30c; --warn: #fab219; --serious: #ec835a; --critical: #d03b3b;
  --ok-text: #006300;

  /* --- chart chrome --- */
  --grid:     #e6e4dd;
  --axis:     #c6c3ba;
  --chart-bg: transparent;

  /* --- type --- */
  --font-body: "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-display: "Instrument Serif", Georgia, "Times New Roman", serif;
  --font-ui: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;

  /* --- geometry --- */
  --col: 760px;
  --col-bleed: 900px;
  --col-wide: 1060px;
  --r-sm: 6px; --r: 10px; --r-lg: 16px; --r-xl: 24px;

  color-scheme: light;
}

[data-theme="dark"] {
  --page:        #0d0d0d;
  --surface:     #171717;
  --surface-2:   #1e1e1d;
  --ink:         #f7f6f3;
  --ink-2:       #c3c2b7;
  --ink-3:       #898781;
  --hairline:    #2c2c2a;
  --hairline-2:  #232322;
  --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 24px -12px rgba(0,0,0,.6);
  --shadow-lg:   0 2px 4px rgba(0,0,0,.4), 0 24px 56px -24px rgba(0,0,0,.7);

  --accent-soft: rgba(57,135,229,.14);

  --s1: #3987e5; --s2: #d95926; --s3: #199e70; --s4: #c98500;
  --s5: #d55181; --s6: #008300; --s7: #9085e9; --s8: #e66767;

  --ok-text: #0ca30c;
  --grid:  #2c2c2a;
  --axis:  #383835;

  color-scheme: dark;
}

/* --- accent presets ------------------------------------------------ */
[data-accent="blue"]   { --accent:#2a78d6; --accent-ink:#1c5cab; --accent-soft:#eaf2fd; }
[data-accent="indigo"] { --accent:#4a3aa7; --accent-ink:#372a80; --accent-soft:#eeecfa; }
[data-accent="teal"]   { --accent:#0f8f79; --accent-ink:#0a6b5b; --accent-soft:#e6f5f2; }
[data-accent="green"]  { --accent:#1baf7a; --accent-ink:#13805a; --accent-soft:#e7f6f0; }
[data-accent="amber"]  { --accent:#b8730a; --accent-ink:#8d5806; --accent-soft:#fbf1e2; }
[data-accent="rose"]   { --accent:#c9385c; --accent-ink:#9c2846; --accent-soft:#fcecf0; }
[data-accent="plum"]   { --accent:#8a3fa0; --accent-ink:#6a2f7c; --accent-soft:#f6ecf9; }
[data-accent="slate"]  { --accent:#3f4a5a; --accent-ink:#2b3442; --accent-soft:#eef0f3; }

[data-theme="dark"][data-accent="blue"]   { --accent:#5d9ceb; --accent-ink:#8fbcf2; --accent-soft:rgba(93,156,235,.16); }
[data-theme="dark"][data-accent="indigo"] { --accent:#9085e9; --accent-ink:#b3abf1; --accent-soft:rgba(144,133,233,.16); }
[data-theme="dark"][data-accent="teal"]   { --accent:#3fbfa6; --accent-ink:#71d2be; --accent-soft:rgba(63,191,166,.16); }
[data-theme="dark"][data-accent="green"]  { --accent:#3fc793; --accent-ink:#74d8b2; --accent-soft:rgba(63,199,147,.16); }
[data-theme="dark"][data-accent="amber"]  { --accent:#e0a33c; --accent-ink:#ecc077; --accent-soft:rgba(224,163,60,.16); }
[data-theme="dark"][data-accent="rose"]   { --accent:#ec6f8f; --accent-ink:#f39cb2; --accent-soft:rgba(236,111,143,.16); }
[data-theme="dark"][data-accent="plum"]   { --accent:#c07ad4; --accent-ink:#d5a3e2; --accent-soft:rgba(192,122,212,.16); }
[data-theme="dark"][data-accent="slate"]  { --accent:#8fa0b8; --accent-ink:#b3c0d1; --accent-soft:rgba(143,160,184,.16); }

/* --- type presets --------------------------------------------------- */
[data-type="modern"]    { --font-display: "Inter", system-ui, sans-serif; }
[data-type="editorial"] { --font-display: "Instrument Serif", Georgia, serif; }

/* ============================================================
   Base
   ============================================================ */
* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--page);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection { background: var(--accent-soft); }

.ra-shell { min-height: 100vh; padding: 0 20px 120px; }

.ra-paper {
  max-width: var(--col-wide);
  margin: 0 auto;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-xl);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}

.ra-body { padding: 0 clamp(20px, 5vw, 72px) 88px; }

/* ============================================================
   Document masthead (title, subtitle, meta)
   ============================================================ */
.ra-masthead { padding: clamp(36px, 6vw, 68px) 0 clamp(20px, 3vw, 32px); }

.ra-eyebrow {
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;
}
.ra-eyebrow::before {
  content: "";
  width: 22px; height: 2px;
  background: currentColor;
  border-radius: 2px;
  opacity: .55;
}

.ra-title {
  font-family: var(--font-display);
  font-size: clamp(38px, 6vw, 62px);
  line-height: 1.04;
  font-weight: 400;
  letter-spacing: -0.02em;
  margin: 0 0 16px;
  max-width: 18ch;
  text-wrap: balance;
}
[data-type="modern"] .ra-title { font-weight: 660; letter-spacing: -0.035em; }

.ra-subtitle {
  font-size: clamp(17px, 2vw, 20px);
  line-height: 1.5;
  color: var(--ink-2);
  margin: 0 0 30px;
  max-width: 60ch;
  text-wrap: pretty;
}

.ra-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 28px;
  padding-top: 22px;
  border-top: 1px solid var(--hairline);
  font-family: var(--font-ui);
  font-size: 13px;
}
.ra-meta__item { display: flex; flex-direction: column; gap: 2px; }
.ra-meta__k { color: var(--ink-3); font-size: 11px; letter-spacing: .07em; text-transform: uppercase; font-weight: 600; }
.ra-meta__v { color: var(--ink); font-weight: 500; }

/* ============================================================
   Prose
   ============================================================ */
/* Every top-level block sits in the reading column; blocks that carry a
   .ra-bleed element (banners, charts, full-width figures) widen instead of
   being cropped — a wider measure is what makes a chart legible. */
.ra-static-block { max-width: var(--col); margin-inline: auto; }
.ra-static-block.is-bleed { max-width: var(--col-bleed); }
#ra-editor { max-width: none; }

.ra-callout__text[contenteditable]:empty::before,
.ra-lead[contenteditable]:empty::before {
  content: attr(data-placeholder); color: var(--ink-3);
}

.ra-body h1, .ra-body h2, .ra-body h3, .ra-body h4,
.ce-header {
  font-family: var(--font-display);
  color: var(--ink);
  letter-spacing: -0.015em;
  text-wrap: balance;
}
[data-type="modern"] .ra-body h1, [data-type="modern"] .ra-body h2,
[data-type="modern"] .ra-body h3, [data-type="modern"] .ce-header { font-weight: 640; letter-spacing: -0.025em; }

.ra-body h2, h2.ce-header {
  font-size: clamp(27px, 3.4vw, 34px);
  line-height: 1.18;
  font-weight: 400;
  margin: 2.4em 0 .5em;
  padding-top: .5em;
}
.ra-body h3, h3.ce-header {
  font-size: 22px; line-height: 1.3; font-weight: 500;
  margin: 1.9em 0 .4em;
}
.ra-body h4, h4.ce-header {
  font-family: var(--font-ui);
  font-size: 13px; font-weight: 680;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--ink-3);
  margin: 2em 0 .5em;
}

.ra-body p, .ce-paragraph { margin: 0 0 1.1em; text-wrap: pretty; }
.ra-body a, .ce-paragraph a { color: var(--accent); text-decoration-color: color-mix(in srgb, var(--accent) 35%, transparent); text-underline-offset: 3px; }
.ra-body strong { font-weight: 620; }
.ra-body mark, .cdx-marker { background: color-mix(in srgb, var(--accent) 18%, transparent); padding: .1em .15em; border-radius: 3px; }

.ra-body ul, .ra-body ol { padding-left: 1.3em; margin: 0 0 1.2em; }
.ra-body li { margin: .35em 0; }
.ra-body li::marker { color: var(--ink-3); }

.ra-lead {
  font-size: 20px; line-height: 1.55; color: var(--ink-2);
  border-left: 2px solid var(--accent);
  padding-left: 22px;
  margin: 0 0 1.6em;
}

/* ============================================================
   Banner
   ============================================================ */
.ra-banner {
  position: relative;
  width: 100%;
  border-radius: var(--r-lg);
  overflow: hidden;
  isolation: isolate;
  display: flex;
  align-items: flex-end;
  min-height: 220px;
  background: var(--surface-2);
}
.ra-banner--hero { border-radius: 0; margin: 0; min-height: 300px; }
.ra-banner__art { position: absolute; inset: 0; z-index: 0; }
.ra-banner__art svg, .ra-banner__art img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ra-banner__scrim { position: absolute; inset: 0; z-index: 1; }
.ra-banner__inner {
  position: relative; z-index: 2;
  padding: clamp(24px, 4vw, 48px);
  width: 100%;
}
.ra-banner__eyebrow {
  font-family: var(--font-ui); font-size: 11.5px; font-weight: 650;
  letter-spacing: .12em; text-transform: uppercase;
  color: rgba(255,255,255,.82); margin-bottom: 10px;
}
.ra-banner__title {
  font-family: var(--font-display);
  font-size: clamp(28px, 4.4vw, 46px);
  line-height: 1.08; font-weight: 400; letter-spacing: -0.02em;
  color: #fff; margin: 0; max-width: 22ch; text-wrap: balance;
  text-shadow: 0 1px 24px rgba(0,0,0,.22);
}
[data-type="modern"] .ra-banner__title { font-weight: 650; letter-spacing: -0.03em; }
.ra-banner__sub { color: rgba(255,255,255,.86); margin: 12px 0 0; max-width: 52ch; font-size: 16px; }
.ra-banner--light .ra-banner__title { color: var(--ink); text-shadow: none; }

/* A section banner renders its title as an <h2>, which sits inside .ra-body and
   would otherwise inherit the prose heading colour and margins. These overrides
   carry higher specificity on purpose — do not lower it. */
.ra-body .ra-banner__title,
.ra-paper .ra-banner__title {
  color: #fff;
  margin: 0;
  padding-top: 0;
  font-size: clamp(28px, 4.4vw, 46px);
  line-height: 1.08;
  font-weight: 400;
  letter-spacing: -0.02em;
}
[data-type="modern"] .ra-body .ra-banner__title,
[data-type="modern"] .ra-paper .ra-banner__title { font-weight: 650; letter-spacing: -0.03em; }
.ra-body .ra-banner--light .ra-banner__title,
.ra-paper .ra-banner--light .ra-banner__title { color: var(--ink); text-shadow: none; }
.ra-banner--light .ra-banner__eyebrow { color: var(--accent); }
.ra-banner--light .ra-banner__sub { color: var(--ink-2); }

/* ============================================================
   KPI tiles
   ============================================================ */
.ra-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  gap: 1px;
  background: var(--hairline);
  border: 1px solid var(--hairline);
  border-radius: var(--r);
  overflow: hidden;
  margin: 2em 0;
}
.ra-kpi {
  background: var(--surface);
  padding: 20px 22px 18px;
  display: flex; flex-direction: column;
}
.ra-kpi__label {
  font-family: var(--font-ui); font-size: 11.5px; font-weight: 620;
  letter-spacing: .07em; text-transform: uppercase; color: var(--ink-3);
  margin-bottom: 10px;
}
.ra-kpi__value {
  font-family: var(--font-ui);
  font-size: 33px; line-height: 1.05; font-weight: 640;
  letter-spacing: -0.03em; color: var(--ink);
  display: flex; align-items: baseline; gap: 4px;
}
.ra-kpi__unit { font-size: 17px; font-weight: 550; color: var(--ink-2); letter-spacing: 0; }
.ra-kpi__delta {
  display: flex; align-items: baseline; flex-wrap: wrap; gap: 2px 5px;
  margin-top: 9px;
  font-family: var(--font-ui); font-size: 13px; font-weight: 560;
  color: var(--ink-2);
  overflow-wrap: anywhere;
}
.ra-kpi__delta svg { align-self: center; }
.ra-kpi__delta b { font-weight: inherit; white-space: nowrap; }
.ra-kpi__delta em { font-style: normal; color: var(--ink-3); font-weight: 450; }
.ra-kpi__label, .ra-kpi__note { overflow-wrap: anywhere; }
.ra-kpi__delta svg { width: 13px; height: 13px; flex: none; }
.ra-kpi__delta--up   { color: var(--ok-text); }
.ra-kpi__delta--down { color: var(--critical); }
.ra-kpi__note { margin-top: 8px; font-size: 12.5px; color: var(--ink-3); font-family: var(--font-ui); }
.ra-kpi__spark { margin-top: auto; padding-top: 14px; }
.ra-kpi__spark svg { display: block; width: 100%; height: 30px; overflow: visible; }

/* ============================================================
   Figures & charts
   ============================================================ */
.ra-figure { margin: 2.4em 0; }
.ra-figure__frame {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r);
  padding: 22px 22px 16px;
}
.ra-figure__head { margin-bottom: 16px; }
.ra-figure__title {
  font-family: var(--font-ui); font-size: 15.5px; font-weight: 620;
  color: var(--ink); margin: 0; letter-spacing: -0.01em;
}
.ra-figure__sub { font-family: var(--font-ui); font-size: 13px; color: var(--ink-2); margin: 4px 0 0; }
.ra-figure__cap {
  font-family: var(--font-ui); font-size: 12.5px; color: var(--ink-3);
  margin: 10px 2px 0; line-height: 1.5;
}
.ra-figure__cap b { color: var(--ink-2); font-weight: 600; }

.ra-legend { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 14px 0 2px; }
.ra-legend__item {
  display: inline-flex; align-items: center; gap: 7px;
  font-family: var(--font-ui); font-size: 12.5px; color: var(--ink-2);
}
.ra-legend__swatch { width: 10px; height: 10px; border-radius: 3px; flex: none; }

.ra-chart { position: relative; }
.ra-chart svg { display: block; width: 100%; height: auto; overflow: visible; }
.ra-chart text { font-family: var(--font-ui); }

.ra-tip {
  position: absolute; z-index: 20; pointer-events: none;
  background: var(--ink); color: var(--page);
  border-radius: var(--r-sm);
  padding: 8px 11px;
  font-family: var(--font-ui); font-size: 12.5px; line-height: 1.45;
  box-shadow: var(--shadow);
  opacity: 0; transform: translate(-50%, -112%);
  transition: opacity .12s ease;
  white-space: nowrap;
}
.ra-tip[data-show="1"] { opacity: 1; }
.ra-tip__k { font-weight: 640; display: block; margin-bottom: 2px; }
.ra-tip__row { display: flex; align-items: center; gap: 7px; }
.ra-tip__sw { width: 8px; height: 8px; border-radius: 2px; flex: none; }
.ra-tip__v { margin-left: auto; font-variant-numeric: tabular-nums; font-weight: 600; padding-left: 12px; }

/* image figures */
.ra-figure__img { width: 100%; display: block; border-radius: var(--r); background: var(--surface-2); }
.ra-figure--full .ra-figure__img { border-radius: var(--r-lg); }
.ra-imgfallback {
  width: 100%; aspect-ratio: 16/9; border-radius: var(--r);
  display: flex; align-items: center; justify-content: center;
  color: var(--ink-3); font-family: var(--font-ui); font-size: 13px;
  background: linear-gradient(135deg, var(--accent-soft), var(--surface-2));
  border: 1px dashed var(--hairline);
}

/* ============================================================
   Callouts
   ============================================================ */
.ra-callout {
  display: flex; gap: 14px;
  border: 1px solid var(--hairline);
  border-left: 3px solid var(--accent);
  background: var(--surface-2);
  border-radius: var(--r);
  padding: 16px 18px;
  margin: 1.8em 0;
}
.ra-callout__icon { flex: none; width: 19px; height: 19px; margin-top: 2px; color: var(--accent); }
.ra-callout__icon svg { width: 100%; height: 100%; display: block; }
.ra-callout__body { flex: 1; min-width: 0; font-size: 15.5px; line-height: 1.6; color: var(--ink-2); }
.ra-callout__title {
  font-family: var(--font-ui); font-weight: 640; font-size: 14px;
  color: var(--ink); margin-bottom: 4px; letter-spacing: -0.005em;
}
.ra-callout--good     { border-left-color: var(--ok);       }
.ra-callout--good .ra-callout__icon     { color: var(--ok-text); }
.ra-callout--warn     { border-left-color: var(--warn);     }
.ra-callout--warn .ra-callout__icon     { color: #a9750a; }
.ra-callout--critical { border-left-color: var(--critical); }
.ra-callout--critical .ra-callout__icon { color: var(--critical); }
[data-theme="dark"] .ra-callout--warn .ra-callout__icon { color: var(--warn); }

/* ============================================================
   Tables
   ============================================================ */
.ra-table-wrap { margin: 2em 0; overflow-x: auto; }
.ra-table, .tc-table {
  width: 100%; border-collapse: collapse;
  font-family: var(--font-ui); font-size: 14.5px;
}
.ra-table th {
  text-align: left; font-weight: 620; color: var(--ink-3);
  font-size: 11.5px; letter-spacing: .07em; text-transform: uppercase;
  padding: 0 14px 10px; border-bottom: 1px solid var(--hairline);
}
.ra-table td {
  padding: 12px 14px; border-bottom: 1px solid var(--hairline-2);
  color: var(--ink-2); vertical-align: top;
}
.ra-table tr:last-child td { border-bottom: 0; }
.ra-table td:first-child { color: var(--ink); font-weight: 540; }
.ra-table .num { text-align: right; font-variant-numeric: tabular-nums; }

/* ============================================================
   Quotes / dividers / misc
   ============================================================ */
.ra-quote, .cdx-quote {
  margin: 2.2em 0; padding: 0 0 0 26px;
  border-left: 2px solid var(--accent);
}
.ra-quote__text, .cdx-quote__text {
  font-family: var(--font-display); font-size: 23px; line-height: 1.42;
  color: var(--ink); font-weight: 400;
}
[data-type="modern"] .ra-quote__text { font-weight: 520; letter-spacing: -0.015em; }
.ra-quote__by, .cdx-quote__caption {
  font-family: var(--font-ui); font-size: 13px; color: var(--ink-3);
  margin-top: 10px;
}

.ra-rule { border: 0; height: 1px; background: var(--hairline); margin: 3em 0; }
.ra-rule--dots {
  height: auto; background: none; text-align: center;
  color: var(--ink-3); letter-spacing: 1.1em; font-size: 12px;
}
.ra-rule--dots::before { content: "•••"; }

.ra-tag {
  display: inline-block;
  font-family: var(--font-ui); font-size: 11.5px; font-weight: 620;
  letter-spacing: .05em; text-transform: uppercase;
  padding: 4px 9px; border-radius: 100px;
  background: var(--accent-soft); color: var(--accent-ink);
}

.ra-footer {
  max-width: var(--col); margin: 4em auto 0; padding-top: 26px;
  border-top: 1px solid var(--hairline);
  font-family: var(--font-ui); font-size: 12.5px; color: var(--ink-3);
  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;
}

/* ============================================================
   Toolbar (edit mode chrome — never exported)
   ============================================================ */
.ra-bar {
  position: sticky; top: 0; z-index: 200;
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding: 10px clamp(14px, 3vw, 26px);
  background: color-mix(in srgb, var(--page) 88%, transparent);
  backdrop-filter: blur(14px) saturate(1.6);
  border-bottom: 1px solid var(--hairline);
  font-family: var(--font-ui);
}
.ra-bar__brand {
  font-size: 12.5px; font-weight: 620; color: var(--ink-2);
  display: flex; align-items: center; gap: 8px; margin-right: auto;
  min-width: 0;
}
.ra-bar__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex: none; }
.ra-bar__status { color: var(--ink-3); font-weight: 450; font-size: 12px; }
.ra-btn {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--font-ui); font-size: 12.5px; font-weight: 560;
  color: var(--ink-2); background: var(--surface);
  border: 1px solid var(--hairline); border-radius: 8px;
  padding: 7px 11px; cursor: pointer;
  transition: background .12s ease, color .12s ease, border-color .12s ease;
  white-space: nowrap;
}
.ra-btn:hover { background: var(--surface-2); color: var(--ink); border-color: var(--ink-3); }
.ra-btn svg { width: 14px; height: 14px; }
.ra-btn--primary { background: var(--accent); color: var(--on-accent); border-color: transparent; }
.ra-btn--primary:hover { background: var(--accent-ink); color: var(--on-accent); }
[data-theme="dark"] .ra-btn--primary { color: #10100f; }

/* block settings popovers inside custom tools */
.ra-tool-bar {
  display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
  margin-bottom: 10px; opacity: 0; transition: opacity .15s ease;
  font-family: var(--font-ui);
}
.ce-block:hover .ra-tool-bar, .ra-tool-bar:focus-within { opacity: 1; }
.ra-chip {
  font-family: var(--font-ui); font-size: 11.5px; font-weight: 550;
  border: 1px solid var(--hairline); background: var(--surface);
  color: var(--ink-2); border-radius: 100px; padding: 3px 10px; cursor: pointer;
}
.ra-chip:hover { border-color: var(--accent); color: var(--accent); }
.ra-chip[aria-pressed="true"] { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.ra-input {
  font-family: var(--font-ui); font-size: 12.5px;
  border: 1px solid var(--hairline); background: var(--surface); color: var(--ink);
  border-radius: 6px; padding: 5px 8px; min-width: 0;
}
.ra-input--wide { width: 100%; }
.ra-editnote {
  font-family: var(--font-ui); font-size: 11.5px; color: var(--ink-3);
  margin-top: 8px;
}

/* ============================================================
   Editor.js integration
   ============================================================ */
.codex-editor { padding: 0 !important; }
.codex-editor__redactor { padding-bottom: 120px !important; }
.ce-block__content, .ce-toolbar__content { max-width: var(--col) !important; }
.ce-block__content:has(.ra-bleed) { max-width: var(--col-bleed) !important; }
.ce-paragraph { line-height: inherit; }
.ce-block--selected .ce-block__content { background: var(--accent-soft); border-radius: var(--r-sm); }
.ce-toolbar__plus, .ce-toolbar__settings-btn { color: var(--ink-2); }
.ce-popover { --color-background: var(--surface); --color-text-primary: var(--ink); border-color: var(--hairline) !important; }
.cdx-search-field { background: var(--surface-2) !important; border-color: var(--hairline) !important; }
/* Editor.js ships a spreadsheet-looking table; a report table wants rules,
   not a grid, so the vertical borders go and the rows keep a hairline. */
.tc-wrap {
  --color-border: transparent;
  --color-text-secondary: var(--ink-3);
  font-family: var(--font-ui); font-size: 14.5px;
  border: 0; margin: 1.6em 0;
}
.tc-table { border: 0; }
.tc-row { border-bottom: 1px solid var(--hairline-2); }
.tc-row:last-child { border-bottom: 0; }
.tc-row--heading { border-bottom: 1px solid var(--hairline); }
.tc-cell { color: var(--ink-2); padding: 12px 14px; border: 0; }
.tc-cell:first-child { padding-left: 0; color: var(--ink); font-weight: 540; }
.tc-row--heading .tc-cell {
  color: var(--ink-3); font-weight: 620; font-size: 11.5px;
  letter-spacing: .07em; text-transform: uppercase; padding-bottom: 10px;
}
.cdx-list { color: inherit; }
.ce-inline-toolbar { --color-background: var(--surface); }

/* ============================================================
   Print / PDF
   ============================================================ */
@media print {
  :root { --page: #fff; --surface: #fff; }
  body { background: #fff; font-size: 11pt; }
  .ra-bar, .ra-tool-bar, .ce-toolbar, .ra-editnote { display: none !important; }
  .ra-shell { padding: 0; }
  .ra-paper { border: 0; border-radius: 0; box-shadow: none; max-width: none; }
  .ra-body { padding: 0 12mm 12mm; }
  .ra-figure, .ra-kpis, .ra-callout, .ra-banner { break-inside: avoid; }
  h2, h3 { break-after: avoid; }
  a { color: inherit; text-decoration: none; }
}

@media (max-width: 700px) {
  body { font-size: 16px; }
  .ra-bar__brand { width: 100%; }
  .ra-bar__brand > span:not(.ra-bar__status) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .codex-editor__redactor { padding-bottom: 60px !important; }
  .tc-wrap { overflow-x: auto; }
  .ra-shell { padding: 0 10px 60px; }
  .ra-paper { border-radius: var(--r-lg); }
  .ra-kpis { grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); }
  .ra-kpi__value { font-size: 27px; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}
